questionvariables.text:
stack_include("contribl://prooflib.mac");
proof_steps:[
["gap","Identify the uncertainty: do varieties respond differently to water?"],
["evidence","Specify evidence: compare varieties at each irrigation level."],
["design","Plan a feasible trial that crosses variety with irrigation and uses replication."],
["measure","Measure yields and relevant conditions that may influence interpretation."],
["infer","Compare varietal contrasts across irrigation regimes, then state limitations."]
];
ta:proof("gap","evidence","design","measure","infer");
proof_steps:random_permutation(proof_steps);
